import { ScrapingResult, CustomProxy } from '../types';

const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 40000, signal?: AbortSignal): Promise<Response> => {
  if (signal?.aborted) throw new DOMException('Aborted', 'AbortError');
  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);

  if (signal) signal.addEventListener('abort', () => {
    clearTimeout(id);
    controller.abort();
  });

  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    clearTimeout(id);
    return response;
  } catch (error) {
    clearTimeout(id);
    throw error;
  }
};

interface ProxyConfig {
  name: string;
  constructUrl: (target: string) => string;
  headers?: (target: string) => Record<string, string>;
  extract: (res: Response) => Promise<string>;
  isMarkdown?: boolean;
}

const DEFAULT_PROXIES: ProxyConfig[] = [
  {
    name: 'Jina Intelligence',
    constructUrl: (target: string) => `https://r.jina.ai/${target}`,
    headers: () => ({ 
      'X-Return-Format': 'markdown',
      'X-With-Generated-Alt': 'true'
    }),
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Jina failed: ${res.status}`);
      return await res.text();
    },
    isMarkdown: true
  },
  {
    name: 'CodeTabs Proxy',
    constructUrl: (target: string) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`CodeTabs failed: ${res.status}`);
      return await res.text();
    }
  },
  {
    name: 'CorsProxy Gateway',
    constructUrl: (target: string) => `https://corsproxy.io/?${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Gateway failed: ${res.status}`);
      return await res.text();
    }
  },
  {
    name: 'AllOrigins Relay',
    constructUrl: (target: string) => `https://api.allorigins.win/get?url=${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      const data = await res.json();
      if (!data.contents) throw new Error("No contents in relay");
      return data.contents;
    }
  }
];

export const scrapeUrl = async (
  url: string, 
  customProxies: CustomProxy[] = [],
  onStatusUpdate?: (status: string) => void,
  signal?: AbortSignal
): Promise<ScrapingResult> => {
  if (!url || !url.startsWith('http')) {
    return { url, content: '', title: '', success: false, error: 'Invalid URL scheme. Must start with http/https.' };
  }

  const activeCustom: ProxyConfig[] = customProxies
    .filter(p => p.isActive && p.ip && p.port)
    .map(p => ({
      name: `Private Node (${p.ip})`,
      constructUrl: (target: string) => `${p.protocol}://${p.ip}:${p.port}/?url=${encodeURIComponent(target)}`,
      extract: async (res: Response) => await res.text()
    }));

  const rotation: ProxyConfig[] = [...activeCustom, ...DEFAULT_PROXIES];
  let lastError: string = '';

  for (const proxy of rotation) {
    if (signal?.aborted) break;
    try {
      onStatusUpdate?.(`Establishing connection via ${proxy.name}...`);

      const response = await fetchWithTimeout(proxy.constructUrl(url), {
        headers: proxy.headers?.(url)
      }, 30000, signal);

      onStatusUpdate?.(`Extracting raw bytes from ${proxy.name}...`);
      const raw = await proxy.extract(response);

      // Relaxed length check to support shorter pages/landing pages
      if (!raw || raw.length < 50) throw new Error("Payload too small or empty.");

      let title = url;
      let cleaned = '';

      if (proxy.isMarkdown) {
        onStatusUpdate?.(`Parsing LLM-optimized Markdown...`);
        const lines = raw.split('\n');
        // Better title extraction from markdown
        const titleLine = lines.find(l => l.startsWith('# '));
        title = titleLine ? titleLine.replace('# ', '').trim() : url;
        cleaned = raw;
      } else {
        onStatusUpdate?.(`Sanitizing HTML DOM structure...`);
        const doc = new DOMParser().parseFromString(raw, 'text/html');
        doc.querySelectorAll('script, style, noscript, iframe, nav, footer, ads, svg, link').forEach(el => el.remove());
        title = doc.title || url;
        const main = (doc.querySelector('main, article, #content, .post-content') || doc.body) as HTMLElement;
        cleaned = main.innerText || main.textContent || '';
      }

      cleaned = cleaned.replace(/\s+/g, ' ').trim().slice(0, 45000);

      if (cleaned.length < 50) throw new Error("Content sanitized to near-zero.");

      onStatusUpdate?.(`Success: Data packet prepared.`);
      return { url, content: cleaned, title, success: true };
    } catch (err: any) {
      console.warn(`Proxy ${proxy.name} failed:`, err);
      lastError = err.message;
      onStatusUpdate?.(`Retry: Proxy node ${proxy.name} bypassed.`);
    }
  }

  return { url, content: '', title: '', success: false, error: `Scraping failed: ${lastError || 'All nodes unreachable.'}` };
};

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisCriteria, AnalysisResult, ModelType, AdminSettings, Recommendation } from "../types";

const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    seoScore: { type: Type.NUMBER, description: "Score from 0-100 for SEO optimization." },
    eeatScore: { type: Type.NUMBER, description: "Score from 0-100 for E-E-A-T compliance." },
    llmOptimizationScore: { type: Type.NUMBER, description: "Score from 0-100 for LLM readability and extraction." },
    isYMYL: { 
        type: Type.BOOLEAN, 
        description: "True if content is high-stakes (Medical, Finance, Legal)." 
    },
    summary: { type: Type.STRING },
    strengths: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    weaknesses: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    recommendations: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING },
          priority: { type: Type.STRING },
          action: { type: Type.STRING },
          description: { type: Type.STRING },
          affectedContent: { type: Type.STRING },
          fixSteps: { 
            type: Type.ARRAY, 
            items: { type: Type.STRING }
          },
          expectedImpact: { type: Type.STRING }
        },
        required: ['category', 'priority', 'action', 'description', 'affectedContent', 'fixSteps', 'expectedImpact']
      }
    },
    keywordGaps: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    sentiment: { type: Type.STRING }
  },
  required: ['seoScore', 'eeatScore', 'llmOptimizationScore', 'isYMYL', 'summary', 'strengths', 'weaknesses', 'recommendations']
};

export const analyzeContent = async (
  url: string,
  pageTitle: string,
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType,
  adminSettings: AdminSettings
): Promise<AnalysisResult> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY not configured.");

  const ai = new GoogleGenAI({ apiKey });

  const knowledgeBaseContext = adminSettings.instructionFiles.length > 0 
    ? `\n\nREFERENCE MATERIALS:\n${adminSettings.instructionFiles.map(f => `--- FILE: ${f.name} ---\n${f.content}`).join('\n')}`
    : "";

  const strictnessInstructions = {
    low: "Baseline check. Be lenient.",
    medium: "Standard professional audit.",
    high: "Strict compliance. Penalize generic advice."
  };

  let finalPrompt = adminSettings.promptTemplate
    .replace(/{{url}}/g, url)
    .replace(/{{content}}/g, content.slice(0, 45000))
    .replace(/{{focusArea}}/g, criteria.focusArea)
    .replace(/{{strictness}}/g, strictnessInstructions[criteria.strictness])
    .replace(/{{customInstructions}}/g, criteria.customInstructions || "None");

  finalPrompt += knowledgeBaseContext;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: finalPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: criteria.strictness === 'high' ? 0.1 : 0.3,
      },
    });

    let jsonText = response.text || "";

    // Cleanup: Remove markdown code fences if present (e.g. ```json ... ```)
    jsonText = jsonText.replace(/^```json\s*/i, '').replace(/\s*```$/, '');

    if (!jsonText) throw new Error("Empty response from model.");

    const parsedData = JSON.parse(jsonText);

    const priorityOrder: Record<string, number> = { 'High': 3, 'Medium': 2, 'Low': 1 };

    if (parsedData.recommendations && Array.isArray(parsedData.recommendations)) {
      parsedData.recommendations.sort((a: Recommendation, b: Recommendation) => 
        (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0)
      );
    } else {
        parsedData.recommendations = [];
    }

    return {
      url,
      pageTitle,
      timestamp: Date.now(),
      ...parsedData
    };
  } catch (error: any) {
    console.error("Analysis Error:", error);
    return {
      url,
      pageTitle,
      timestamp: Date.now(),
      seoScore: 0,
      eeatScore: 0,
      llmOptimizationScore: 0,
      isYMYL: false,
      summary: "Analysis Error",
      strengths: [],
      weaknesses: [],
      recommendations: [],
      keywordGaps: [],
      sentiment: "Neutral",
      error: error.message || "Unknown AI error."
    };
  }
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { AnalysisMode, AppState, ModelType, AnalysisCriteria, AnalysisResult, AdminSettings, CustomProxy } from './types';
import { scrapeUrl } from './services/scraperService';
import { analyzeContent } from './services/geminiService';
import { loadAdminSettings, saveAdminSettings } from './services/adminService';
