import React, { useState, useCallback, useEffect, useRef } from 'react';
import { AnalysisMode, AppState, ModelType, AnalysisCriteria, AnalysisResult, AdminSettings, CustomProxy } from './types';
import { scrapeUrl } from './services/scraperService';
import { analyzeContent } from './services/geminiService';
import { loadAdminSettings, saveAdminSettings } from './services/adminService';
import CriteriaSettings from './components/CriteriaSettings';
import ResultCard from './components/ResultCard';
import AdminPanel from './components/AdminPanel';
import PasswordModal from './components/PasswordModal';
import ProxyModal from './components/ProxyModal';
import CustomSelect from './components/CustomSelect';

const INITIAL_CRITERIA: AnalysisCriteria = {
  focusArea: 'General SEO',
  strictness: 'medium',
  customInstructions: ''
};

const GEO_PROMPT = `
Analyze the following web page content located at: {{url}}

Content Preview:
{{content}}

Analysis Criteria:
- Focus Area: {{focusArea}}
- Strictness Level: {{strictness}}
- User Custom Instructions: {{customInstructions}}

--- AUDIT INSTRUCTIONS ---
You are a Senior SEO Auditor and Content Strategist. Your goal is to analyze the content against high standards of Google's E-E-A-T and modern "Helpful Content" signals.
Use the following strict guidelines to evaluate the content.

1. Authorship & E-E-A-T (Critical)
   - Is there a real, named author? (Generic "Team" or "Staff" is a negative signal).
   - Are there clear credentials, job titles, or links to LinkedIn/Bio pages?
   - Originality: Does the content cite original research, first-hand data, or unique case studies? Or is it just aggregating existing info?
   - Expertise: Are there expert quotes? Note: Quotes in images are NOT readable by crawlers and should be flagged as an issue.

2. Structure & Journalism Style
   - Inverted Pyramid: Does it start with the "Most Important Point" or answer? Avoid academic intros that bury the lede.
   - Headings: Check hierarchy (H1 -> H2 -> H3). H1 must be unique. H2s should be informative (e.g., questions users ask).
   - Sentence Structure: One sentence = One idea. Flag long, complex sentences ("Walls of text").
   - Formatting: Look for tables, numbered lists, and visual breaks. (Tables increase citation rates).

3. AI & LLM Optimization (GEO - Generative Engine Optimization)
   - Direct Answers: Does the content contain concise (40-60 word) definition blocks that AI can easily extract as a featured snippet?
   - Numeric Anchors: Does it use specific data points (e.g., "cited 40% more often") rather than vague claims ("significant growth")?
   - Context: Are user pain points explicitly named and connected to the solution?
   - Entities: Does the content establish clear relationships between key entities (People, Places, Concepts) for Knowledge Graph construction?

4. Technical & UX
   - CTA: Are Call-to-Actions value-led and specific? (Avoid generic "Click here").
   - Internal Links: Are there 2-10 relevant internal links with descriptive anchor text?
   - External Links: Are sources cited? (Opinions/Stats should link to sources).

--- OUTPUT REQUIREMENTS ---
Provide a JSON response with a COMPREHENSIVE list of recommendations (aim for 25-30 granular items).
For each recommendation:
- Priority: High (EEAT/Safety/Broken), Medium (Optimization), Low (Polish).
- Action: Short title.
- Description: What is wrong.
- Affected Content: Quote the exact text, header, or section.
- Fix Steps: Step-by-step instructions (e.g., "1. Change H2 to... 2. Add table comparing X and Y...").
- Expected Impact: Specific benefit (e.g., "Increases extraction rate by AI").

Additionally, provide:
- lsiKeywords: List 5-10 Latent Semantic Indexing keywords that are contextually relevant but missing or underused.
- llmEntities: List 5-10 key entities (Concepts, Organizations, Tech) that an LLM would associate with this topic for knowledge mapping.
- sentiment: An object containing:
    - label: (Positive/Neutral/Negative/Mixed)
    - score: (0-100 where 0 is Negative, 100 is Positive)
    - explanation: Brief analysis of the emotional resonance and tone.

Do NOT be lenient. If the author is anonymous, flag it. If the intro is fluff, flag it. If there are no tables, flag it.
`.trim();

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    mode: AnalysisMode.SINGLE,
    urls: [],
    results: [],
    isAnalyzing: false,
    currentProgress: 0,
    progressStatus: 'Ready',
    selectedModel: ModelType.FLASH,
    criteria: INITIAL_CRITERIA,
    showAdmin: false,
    showProxy: false,
    isAdminAuthenticated: false,
    adminSettings: {
        promptTemplate: GEO_PROMPT,
        instructionFiles: []
    }
  });

  const [customProxies, setCustomProxies] = useState<CustomProxy[]>([]);
  const [inputUrl, setInputUrl] = useState('');
  const [bulkInput, setBulkInput] = useState('');
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const saved = loadAdminSettings();
    if (saved) setState(prev => ({ ...prev, adminSettings: saved }));
    try {
      const savedProxies = localStorage.getItem('content_audit_user_proxies');
      if (savedProxies) setCustomProxies(JSON.parse(savedProxies));
    } catch (e) {}
  }, []);

  // Fix: Calculate targets count in component scope to avoid "Cannot find name 'targets'" error in JSX
  const currentTargetsCount = state.mode === AnalysisMode.SINGLE 
    ? (inputUrl.trim() ? 1 : 0) 
    : bulkInput.split('\n').map(u => u.trim()).filter(Boolean).length;

  const handleStartAnalysis = useCallback(async () => {
    if (abortControllerRef.current) abortControllerRef.current.abort();
    const controller = new AbortController();
    abortControllerRef.current = controller;

    let targets = state.mode === AnalysisMode.SINGLE 
      ? [inputUrl].filter(Boolean) 
      : bulkInput.split('\n').map(u => u.trim()).filter(Boolean);

    if (targets.length === 0) return;

    setState(prev => ({ 
      ...prev, 
      isAnalyzing: true, 
      results: [], 
      currentProgress: 0,
      progressStatus: 'Initializing secure audit...' 
    }));

    const finalResults: AnalysisResult[] = [];

    for (let i = 0; i < targets.length; i++) {
      if (controller.signal.aborted) break;
      const url = targets[i];
      const stepBase = (i / targets.length) * 100;
      const stepSize = 100 / targets.length;

      try {
        // Step 1: Scrape (0-45% of step)
        setState(prev => ({ ...prev, progressStatus: `Connecting to ${url}...`, currentProgress: Math.round(stepBase + (stepSize * 0.1)) }));
        const scrape = await scrapeUrl(url, customProxies, (s) => {
          setState(prev => ({ ...prev, progressStatus: s }));
        }, controller.signal);

        if (controller.signal.aborted) break;

        if (!scrape.success) {
          finalResults.push({ 
              url, 
              timestamp: Date.now(), 
              seoScore: 0, 
              eeatScore: 0, 
              llmOptimizationScore: 0, 
              isYMYL: false, 
              summary: "Analysis Halted", 
              strengths: [], 
              weaknesses: [], 
              recommendations: [], 
              keywordGaps: [],
              lsiKeywords: [],
              llmEntities: [],
              sentiment: { label: 'Neutral', score: 50, explanation: 'Analysis failed.' },
              error: scrape.error 
          });
        } else {
          // Step 2: AI Process (45-100% of step)
          setState(prev => ({ ...prev, progressStatus: `Gemini ${state.selectedModel} performing semantic audit...`, currentProgress: Math.round(stepBase + (stepSize * 0.5)) }));
          const analysis = await analyzeContent(url, scrape.title, scrape.content, state.criteria, state.selectedModel, state.adminSettings);
          finalResults.push(analysis);
        }
      } catch (err: any) {
        finalResults.push({ 
            url, 
            timestamp: Date.now(), 
            seoScore: 0, 
            eeatScore: 0, 
            llmOptimizationScore: 0, 
            isYMYL: false, 
            summary: "System Error", 
            strengths: [], 
            weaknesses: [], 
            recommendations: [], 
            keywordGaps: [],
            lsiKeywords: [],
            llmEntities: [],
            sentiment: { label: 'Neutral', score: 50, explanation: 'System error.' },
            error: err.message 
        });
      }

      setState(prev => ({ 
        ...prev, 
        results: [...finalResults], 
        currentProgress: Math.round(((i + 1) / targets.length) * 100) 
      }));
    }

    setState(prev => ({ ...prev, isAnalyzing: false, progressStatus: 'Audit Complete' }));
  }, [state.mode, state.criteria, state.selectedModel, state.adminSettings, inputUrl, bulkInput, customProxies]);

  const handleStopAnalysis = () => {
    abortControllerRef.current?.abort();
    setState(prev => ({ ...prev, isAnalyzing: false, progressStatus: 'Session Terminated' }));
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] text-slate-900 flex flex-col font-inter pb-16">
      {/* Navigation */}
      <nav className="fixed w-full z-40 top-0 start-0 border-b border-white/20 bg-white/80 backdrop-blur-md shadow-sm">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center shadow-lg transform hover:rotate-3 transition-transform">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </div>
              <span className="font-bold text-xl tracking-tight hidden sm:inline-block">ContentAudit<span className="text-blue-600">AI</span></span>
            </div>

            <div className="flex items-center gap-2">
               <div className="w-44 hidden md:block">
                 <CustomSelect 
                    value={state.selectedModel} 
                    onChange={(val) => setState(prev => ({ ...prev, selectedModel: val as ModelType }))} 
                    options={[
                        { value: ModelType.FLASH, label: 'Gemini 3 Flash' },
                        { value: ModelType.PRO, label: 'Gemini 3 Pro' },
                        { value: ModelType.FLASH_2_5, label: 'Flash 2.5 Preview' }
                    ]} 
                 />
               </div>
               <div className="flex items-center border-l border-slate-100 ml-2 pl-2 gap-1">
                 <button onClick={() => setState(prev => ({ ...prev, showProxy: true }))} className="p-2 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg></button>
                 <button onClick={() => state.isAdminAuthenticated ? setState(prev => ({...prev, showAdmin: true})) : setShowPasswordModal(true)} className="p-2 text-slate-500 hover:text-purple-600 hover:bg-purple-50 rounded-lg transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066-1.543.94-3.31-.826-2.37-2.37-1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg></button>
               </div>
            </div>
          </div>
        </div>
      </nav>

      <main className="container mx-auto px-4 py-8 mt-16 flex-grow">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* Sidebar Controls */}
          <div className="col-span-1 lg:col-span-4 xl:col-span-3 space-y-6">
            <div className={`bg-white p-6 rounded-2xl shadow-xl border border-white transition-all duration-500 ${state.isAnalyzing ? 'scanning-effect ring-2 ring-blue-500/20' : ''}`}>
              <div className="flex p-1 bg-slate-100 rounded-xl mb-6">
                <button onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.SINGLE }))} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${state.mode === AnalysisMode.SINGLE ? 'bg-white shadow-md text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}>Single URL</button>
                <button onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.BULK }))} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${state.mode === AnalysisMode.BULK ? 'bg-white shadow-md text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}>Bulk Audit</button>
              </div>

              {state.mode === AnalysisMode.SINGLE ? (
                <div className="relative group">
                  <input type="text" placeholder="https://example.com" value={inputUrl} onChange={(e) => setInputUrl(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-blue-100 focus:border-blue-500 transition-all outline-none" />
                </div>
              ) : (
                <textarea placeholder="Paste URLs (one per line)..." value={bulkInput} onChange={(e) => setBulkInput(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm h-32 focus:ring-2 focus:ring-blue-100 focus:border-blue-500 transition-all outline-none resize-none" />
              )}

              <button 
                disabled={state.isAnalyzing && state.currentProgress < 10}
                onClick={state.isAnalyzing ? handleStopAnalysis : handleStartAnalysis} 
                className={`mt-6 w-full py-4 rounded-xl font-bold text-white shadow-xl transform active:scale-95 transition-all ${state.isAnalyzing ? 'bg-red-500 hover:bg-red-600' : 'bg-gradient-to-r from-blue-600 to-indigo-600 hover:brightness-110'}`}
              >
                {state.isAnalyzing ? 'Abort Operation' : 'Initiate Intelligence Audit'}
              </button>

              {state.isAnalyzing && (
                <div className="mt-6 space-y-2 animate-in fade-in slide-in-from-top-2">
                  <div className="flex justify-between text-[10px] font-bold uppercase tracking-widest text-slate-400">
                    <span>Audit Status</span>
                    <span className="text-blue-600">{state.currentProgress}%</span>
                  </div>
                  <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden">
                    <div 
                        className="h-full progress-shimmer transition-all duration-500 ease-out rounded-full" 
                        style={{ width: `${state.currentProgress}%` }} 
                    />
                  </div>
                  <div className="flex items-center gap-2 mt-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse"></div>
                    <p className="text-[11px] text-slate-500 font-medium italic truncate">{state.progressStatus}</p>
                  </div>
                </div>
              )}
            </div>

            <CriteriaSettings criteria={state.criteria} onChange={(c) => setState(prev => ({ ...prev, criteria: c }))} />
          </div>

          {/* Results Area */}
          <div className="col-span-1 lg:col-span-8 xl:col-span-9">
             {state.results.length === 0 && !state.isAnalyzing ? (
               <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[500px] border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white/40 p-12 text-center animate-in zoom-in-95">
                 <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mb-6 shadow-inner">
                    <svg className="w-12 h-12 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" /></svg>
                 </div>
                 <h3 className="text-2xl font-bold text-slate-700">Intelligence Ready</h3>
                 <p className="text-slate-500 max-w-xs mx-auto mt-2">Input target URLs to begin multi-vector content auditing and GEO assessment.</p>
               </div>
             ) : (
               <div className="space-y-10">
                 {state.results.map((result, index) => (
                    <div key={index} className="animate-slide-up" style={{ animationDelay: `${index * 0.1}s` }}>
                        <ResultCard result={result} />
                    </div>
                 ))}
                 {/* Fix: use currentTargetsCount instead of targets.length which was out of scope */}
                 {state.isAnalyzing && state.results.length < currentTargetsCount && (
                    <div className="bg-white/50 border border-dashed border-blue-200 rounded-3xl p-12 flex flex-col items-center justify-center gap-4 animate-pulse">
                        <div className="w-10 h-10 border-4 border-blue-100 border-t-blue-500 rounded-full animate-spin"></div>
                        <p className="text-sm font-semibold text-blue-500">Processing next segment...</p>
                    </div>
                 )}
               </div>
             )}
          </div>
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 w-full bg-slate-900 text-slate-400 text-[10px] py-2 px-6 z-50 flex justify-between border-t border-slate-700/50 backdrop-blur-sm">
          <div className="flex gap-4">
            <span className="mono opacity-50">STATUS: {state.isAnalyzing ? 'ACTIVE_AUDIT' : 'IDLE'}</span>
            <span className="mono opacity-50">THREADS: 1</span>
          </div>
          <span className="mono">DEVELOPED_FOR_ANTAKO_NP // v1.2.5-stable</span>
      </footer>

      {state.showAdmin && <AdminPanel settings={state.adminSettings} onSave={(s) => { setState(prev => ({...prev, adminSettings: s})); saveAdminSettings(s); }} onClose={() => setState(prev => ({ ...prev, showAdmin: false }))} />}
      {state.showProxy && <ProxyModal onClose={() => setState(prev => ({ ...prev, showProxy: false }))} onSave={setCustomProxies} initialProxies={customProxies} />}
      {showPasswordModal && <PasswordModal onAuthenticated={() => { setState(prev => ({...prev, isAdminAuthenticated: true, showAdmin: true})); setShowPasswordModal(false); }} onClose={() => setShowPasswordModal(false)} />}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisCriteria, AnalysisResult, ModelType, AdminSettings, Recommendation } from "../types";

const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    seoScore: { type: Type.NUMBER, description: "Score from 0-100 for SEO optimization." },
    eeatScore: { type: Type.NUMBER, description: "Score from 0-100 for E-E-A-T compliance." },
    llmOptimizationScore: { type: Type.NUMBER, description: "Score from 0-100 for LLM readability and extraction." },
    isYMYL: { 
        type: Type.BOOLEAN, 
        description: "True if content is high-stakes (Medical, Finance, Legal)." 
    },
    summary: { type: Type.STRING },
    strengths: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    weaknesses: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    recommendations: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING },
          priority: { type: Type.STRING },
          action: { type: Type.STRING },
          description: { type: Type.STRING },
          affectedContent: { type: Type.STRING },
          fixSteps: { 
            type: Type.ARRAY, 
            items: { type: Type.STRING }
          },
          expectedImpact: { type: Type.STRING }
        },
        required: ['category', 'priority', 'action', 'description', 'affectedContent', 'fixSteps', 'expectedImpact']
      }
    },
    keywordGaps: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    lsiKeywords: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Latent Semantic Indexing keywords relevant to the content."
    },
    llmEntities: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Key entities (People, Orgs, Concepts) for Knowledge Graph."
    },
    sentiment: { 
      type: Type.OBJECT,
      properties: {
        label: { type: Type.STRING, description: "Positive, Negative, Neutral, or Mixed" },
        score: { type: Type.NUMBER, description: "0-100 score where 0 is Negative, 100 is Positive" },
        explanation: { type: Type.STRING, description: "Brief analysis of emotional tone" }
      },
      required: ['label', 'score', 'explanation']
    }
  },
  required: ['seoScore', 'eeatScore', 'llmOptimizationScore', 'isYMYL', 'summary', 'strengths', 'weaknesses', 'recommendations', 'lsiKeywords', 'llmEntities', 'sentiment']
};

export const analyzeContent = async (
  url: string,
  pageTitle: string,
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType,
  adminSettings: AdminSettings
): Promise<AnalysisResult> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY not configured.");

  const ai = new GoogleGenAI({ apiKey });

  const knowledgeBaseContext = adminSettings.instructionFiles.length > 0 
    ? `\n\nREFERENCE MATERIALS:\n${adminSettings.instructionFiles.map(f => `--- FILE: ${f.name} ---\n${f.content}`).join('\n')}`
    : "";

  const strictnessInstructions = {
    low: "Baseline check. Be lenient.",
    medium: "Standard professional audit.",
    high: "Strict compliance. Penalize generic advice."
  };

  let finalPrompt = adminSettings.promptTemplate
    .replace(/{{url}}/g, url)
    .replace(/{{content}}/g, content.slice(0, 45000))
    .replace(/{{focusArea}}/g, criteria.focusArea)
    .replace(/{{strictness}}/g, strictnessInstructions[criteria.strictness])
    .replace(/{{customInstructions}}/g, criteria.customInstructions || "None");

  finalPrompt += knowledgeBaseContext;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: finalPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: criteria.strictness === 'high' ? 0.1 : 0.3,
        maxOutputTokens: 8192,
      },
    });

    let jsonText = response.text || "";

    // Cleanup: Remove markdown code fences if present (e.g. ```json ... ```)
    jsonText = jsonText.replace(/^```json\s*/i, '').replace(/\s*```$/, '');

    if (!jsonText) throw new Error("Empty response from model.");

    const parsedData = JSON.parse(jsonText);

    const priorityOrder: Record<string, number> = { 'High': 3, 'Medium': 2, 'Low': 1 };

    if (parsedData.recommendations && Array.isArray(parsedData.recommendations)) {
      parsedData.recommendations.sort((a: Recommendation, b: Recommendation) => 
        (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0)
      );
    } else {
        parsedData.recommendations = [];
    }

    return {
      url,
      pageTitle,
      timestamp: Date.now(),
      ...parsedData
    };
  } catch (error: any) {
    console.error("Analysis Error:", error);
    return {
      url,
      pageTitle,
      timestamp: Date.now(),
      seoScore: 0,
      eeatScore: 0,
      llmOptimizationScore: 0,
      isYMYL: false,
      summary: "Analysis Error",
      strengths: [],
      weaknesses: [],
      recommendations: [],
      keywordGaps: [],
      lsiKeywords: [],
      llmEntities: [],
      sentiment: { label: "Unknown", score: 0, explanation: "Failed to analyze." },
      error: error.message || "Unknown AI error."
    };
  }
};

