                      <button onClick={() => { navigator.clipboard.writeText(generatedPrompt); alert("Copied!"); }} className="px-8 py-3 bg-slate-900 text-white font-bold rounded-2xl shadow-xl hover:bg-black transition-all">Copy Prompt</button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

