import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import { AnalysisResult } from "../types";

// --- Color Palette (Modern & Minimal) ---
const COLORS = {
  primary: [59, 130, 246] as [number, number, number],    // Blue 500
  secondary: [99, 102, 241] as [number, number, number],  // Indigo 500
  slateDark: [30, 41, 59] as [number, number, number],    // Slate 800
  slateMed: [71, 85, 105] as [number, number, number],    // Slate 600
  slateLight: [148, 163, 184] as [number, number, number],// Slate 400
  bgLight: [248, 250, 252] as [number, number, number],   // Slate 50
  white: [255, 255, 255] as [number, number, number],
  border: [226, 232, 240] as [number, number, number],

  // Status Colors
  success: [16, 185, 129] as [number, number, number],
  warning: [245, 158, 11] as [number, number, number],
  danger: [239, 68, 68] as [number, number, number],
};

export const generatePdfReport = (result: AnalysisResult) => {
  // A4 Landscape
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  const pageWidth = doc.internal.pageSize.width; // 297mm
  const pageHeight = doc.internal.pageSize.height; // 210mm
  const margin = 14;
  let cursorY = margin;

  // --- Helpers ---
  const drawFooter = () => {
    const pageCount = doc.getNumberOfPages();
    for (let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(...COLORS.slateLight);

        // Left Side: Contact
        doc.textWithLink("// work in progress for fixes & suggestions contact Antako", margin, pageHeight - 8, { url: 'https://t.me/antako_np' });

        // Right Side: Page Number
        doc.text(`Page ${i} of ${pageCount}`, pageWidth - margin, pageHeight - 8, { align: 'right' });
    }
  };

  const drawContainer = (x: number, y: number, w: number, h: number, color: [number, number, number] = COLORS.white) => {
     doc.setFillColor(...color);
     doc.setDrawColor(...COLORS.border);
     doc.roundedRect(x, y, w, h, 3, 3, 'FD');
  };

  // --- PAGE 1: DASHBOARD ---

  // 1. Header
  doc.setFont("helvetica", "bold");
  doc.setFontSize(24);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Content Audit Report", margin, cursorY + 8);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(...COLORS.slateMed);
  doc.text(new Date().toLocaleDateString(), pageWidth - margin, cursorY + 8, { align: 'right' });

  cursorY += 15;

  // 2. URL & Meta
  doc.setDrawColor(...COLORS.border);
  doc.setLineWidth(0.1);
  doc.line(margin, cursorY, pageWidth - margin, cursorY);
  cursorY += 6;

  doc.setFontSize(9);
  doc.setTextColor(...COLORS.slateLight);
  doc.text("TARGET URL", margin, cursorY + 3);
  doc.setFontSize(11);
  doc.setTextColor(...COLORS.primary);
  doc.text(result.url, margin + 25, cursorY + 3);

  cursorY += 10;

  // 3. Score Overview (Using 3 distinct blocks)
  const blockGap = 5;
  const blockW = (pageWidth - (margin * 2) - (blockGap * 2)) / 3;
  const blockH = 25;

  const drawStat = (label: string, score: number, x: number) => {
      drawContainer(x, cursorY, blockW, blockH, COLORS.bgLight);

      doc.setFontSize(8);
      doc.setTextColor(...COLORS.slateMed);
      doc.setFont("helvetica", "bold");
      doc.text(label.toUpperCase(), x + 6, cursorY + 7);

      doc.setFontSize(18);
      // Color logic
      let sc = COLORS.success;
      if (score < 50) sc = COLORS.danger;
      else if (score < 80) sc = COLORS.warning;

      doc.setTextColor(...sc);
      doc.text(`${score}`, x + 6, cursorY + 18);

      doc.setFontSize(10);
      doc.setTextColor(...COLORS.slateLight);
      doc.text("/ 100", x + 16 + (score > 9 ? 10 : 5), cursorY + 18);

      // Simple bar at bottom
      doc.setFillColor(...sc);
      doc.rect(x + 6, cursorY + 21, (blockW - 12) * (score / 100), 1.5, 'F');
  };

  drawStat("SEO Health", result.seoScore, margin);
  drawStat("E-E-A-T Score", result.eeatScore, margin + blockW + blockGap);
  drawStat("AI Readiness", result.llmOptimizationScore, margin + (blockW + blockGap) * 2);

  cursorY += blockH + 10;

  // 4. Executive Summary
  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin, right: margin },
      head: [['EXECUTIVE SUMMARY']],
      body: [[result.summary]],
      theme: 'plain',
      headStyles: {
          fillColor: COLORS.white,
          textColor: COLORS.secondary,
          fontSize: 11,
          fontStyle: 'bold',
          cellPadding: { top: 0, bottom: 2, left: 0 }
      },
      bodyStyles: {
          textColor: COLORS.slateMed,
          fontSize: 10,
          cellPadding: 0,
          lineHeight: 1.4
      },
      columnStyles: {
          0: { cellWidth: 'auto' }
      }
  });

  // Update cursor based on table end
  cursorY = (doc as any).lastAutoTable.finalY + 10;

  // 5. Strengths & Weaknesses (Side-by-Side Tables)
  const halfPage = (pageWidth - (margin * 2)) / 2;

  const strengthsBody = result.strengths.map(s => [`• ${s}`]);
  const weaknessesBody = result.weaknesses.map(w => [`• ${w}`]);

  // Strengths Table
  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin },
      tableWidth: halfPage - 4,
      head: [['KEY STRENGTHS']],
      body: strengthsBody,
      theme: 'plain',
      headStyles: {
          textColor: COLORS.success,
          fontSize: 10,
          fontStyle: 'bold',
          cellPadding: { bottom: 3, left: 0 }
      },
      bodyStyles: {
          textColor: COLORS.slateDark,
          fontSize: 9,
          cellPadding: { top: 1, bottom: 1, left: 2 },
          overflow: 'linebreak'
      }
  });

  // Weaknesses Table
  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin + halfPage + 4 },
      tableWidth: halfPage - 4,
      head: [['CRITICAL ISSUES']],
      body: weaknessesBody,
      theme: 'plain',
      headStyles: {
          textColor: COLORS.danger,
          fontSize: 10,
          fontStyle: 'bold',
          cellPadding: { bottom: 3, left: 0 }
      },
      bodyStyles: {
          textColor: COLORS.slateDark,
          fontSize: 9,
          cellPadding: { top: 1, bottom: 1, left: 2 },
          overflow: 'linebreak'
      }
  });

  // --- PAGE 2: SEMANTICS & SENTIMENT ---
  doc.addPage();
  cursorY = margin;

  // Sentiment Block
  doc.setFontSize(14);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Sentiment & Semantic Profile", margin, cursorY + 6);
  cursorY += 15;

  const sentimentLabel = `${result.sentiment.label} (${result.sentiment.score}/100)`;

  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin, right: margin },
      head: [[`SENTIMENT: ${sentimentLabel}`]],
      body: [[result.sentiment.explanation]],
      theme: 'grid',
      headStyles: {
          fillColor: result.sentiment.score > 60 ? COLORS.success : result.sentiment.score < 40 ? COLORS.danger : COLORS.warning,
          textColor: COLORS.white,
          fontSize: 10,
          fontStyle: 'bold'
      },
      bodyStyles: {
          textColor: COLORS.slateMed,
          fontSize: 9,
          cellPadding: 4,
          fontStyle: 'italic'
      }
  });

  cursorY = (doc as any).lastAutoTable.finalY + 10;

  // Keywords Tables (3 columns simulated via autoTable)
  // Since autoTable is row-based, we find max length
  const maxLen = Math.max(result.keywordGaps.length, result.lsiKeywords.length, result.llmEntities.length);
  const keywordRows = [];

  for(let i = 0; i < maxLen; i++) {
      keywordRows.push([
          result.keywordGaps[i] || '',
          result.lsiKeywords[i] || '',
          result.llmEntities[i] || ''
      ]);
  }

  (autoTable as any)(doc, {
      startY: cursorY,
      head: [['KEYWORD GAPS', 'LSI OPPORTUNITIES', 'LLM ENTITIES']],
      body: keywordRows,
      theme: 'grid',
      headStyles: {
          fillColor: COLORS.bgLight,
          textColor: COLORS.slateDark,
          fontStyle: 'bold',
          lineWidth: 0.1,
          lineColor: COLORS.border,
      },
      styles: {
          fontSize: 8,
          cellPadding: 2,
          textColor: COLORS.slateMed
      }
  });

  // --- PAGE 3: ACTION PLAN ---
  doc.addPage();
  cursorY = margin;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(18);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Optimization Action Plan", margin, cursorY + 6);
  cursorY += 15;

  const planBody = result.recommendations.map(rec => [
      rec.priority.toUpperCase(),
      rec.category,
      rec.action,
      `${rec.description}\n\nFIX:\n${rec.fixSteps.map(s => `- ${s}`).join('\n')}`,
      rec.expectedImpact
  ]);

  (autoTable as any)(doc, {
      startY: cursorY,
      head: [['PRIORITY', 'AREA', 'ACTION', 'DETAILS & INSTRUCTIONS', 'IMPACT']],
      body: planBody,
      theme: 'grid',
      styles: {
          font: 'helvetica',
          fontSize: 9,
          lineColor: COLORS.border,
          lineWidth: 0.1,
          cellPadding: 4,
          textColor: COLORS.slateMed,
          valign: 'top',
          overflow: 'linebreak'
      },
      headStyles: {
          fillColor: COLORS.bgLight,
          textColor: COLORS.slateDark,
          fontStyle: 'bold',
          lineWidth: 0.1,
          lineColor: COLORS.border,
          halign: 'left'
      },
      // ADJUSTED COLUMN WIDTHS TO FIX "PRIORIT-Y" BREAK
      columnStyles: {
          0: { cellWidth: 30, halign: 'center', fontStyle: 'bold' }, // Increased from 22 to 30
          1: { cellWidth: 25 },
          2: { cellWidth: 50, fontStyle: 'bold', textColor: COLORS.primary },
          3: { cellWidth: 'auto' }, 
          4: { cellWidth: 40, fontSize: 8 }
      },
      didParseCell: (data: any) => {
          if (data.section === 'body' && data.column.index === 0) {
              const p = data.cell.raw;
              if (p === 'HIGH') data.cell.styles.textColor = COLORS.danger;
              else if (p === 'MEDIUM') data.cell.styles.textColor = COLORS.warning;
              else data.cell.styles.textColor = COLORS.success;
          }
      }
  });

  drawFooter();

  // --- NAMING LOGIC ---
  const now = new Date();
  const dateStr = now.toISOString().slice(0, 10).replace(/-/g, ''); // YYYYMMDD
  const timeStr = now.toISOString().slice(11, 16).replace(/:/g, ''); // HHmm

  let hostname = 'domain';
  try {
      hostname = new URL(result.url).hostname.replace(/^www\./, '').toLowerCase();
  } catch (e) {}

  const cleanHostname = hostname
    .replace(/[^a-z0-9]/g, '-') // Replace non-alphanumeric with hyphen
    .replace(/-+/g, '-')        // Collapse multiple hyphens
    .replace(/^-|-$/g, '');     // Trim edges

  const filename = `${cleanHostname}-audit-${dateStr}-${timeStr}.pdf`;
  doc.save(filename);
};

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisCriteria, AnalysisResult, ModelType, AdminSettings, Recommendation } from "../types";

const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    seoScore: { type: Type.NUMBER, description: "Score from 0-100 for SEO optimization." },
    eeatScore: { type: Type.NUMBER, description: "Score from 0-100 for E-E-A-T compliance." },
    llmOptimizationScore: { type: Type.NUMBER, description: "Score from 0-100 for LLM readability and extraction." },
    isYMYL: { 
        type: Type.BOOLEAN, 
        description: "True if content is high-stakes (Medical, Finance, Legal)." 
    },
    summary: { type: Type.STRING },
    strengths: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    weaknesses: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    recommendations: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING },
          priority: { type: Type.STRING },
          action: { type: Type.STRING },
          description: { type: Type.STRING },
          affectedContent: { type: Type.STRING },
          fixSteps: { 
            type: Type.ARRAY, 
            items: { type: Type.STRING }
          },
          expectedImpact: { type: Type.STRING }
        },
        required: ['category', 'priority', 'action', 'description', 'affectedContent', 'fixSteps', 'expectedImpact']
      }
    },
    keywordGaps: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    lsiKeywords: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Latent Semantic Indexing keywords relevant to the content."
    },
    llmEntities: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Key entities (People, Orgs, Concepts) for Knowledge Graph."
    },
    sentiment: { 
      type: Type.OBJECT,
      properties: {
        label: { type: Type.STRING, description: "Positive, Negative, Neutral, or Mixed" },
        score: { type: Type.NUMBER, description: "0-100 score where 0 is Negative, 100 is Positive" },
        explanation: { type: Type.STRING, description: "Brief analysis of emotional tone" }
      },
      required: ['label', 'score', 'explanation']
    }
  },
  required: ['seoScore', 'eeatScore', 'llmOptimizationScore', 'isYMYL', 'summary', 'strengths', 'weaknesses', 'recommendations', 'lsiKeywords', 'llmEntities', 'sentiment']
};

export const analyzeContent = async (
  url: string,
  pageTitle: string,
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType,
  adminSettings: AdminSettings
): Promise<AnalysisResult> => {
  if (!process.env.API_KEY) throw new Error("API_KEY not configured.");

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const knowledgeBaseContext = adminSettings.instructionFiles.length > 0 
    ? `\n\nREFERENCE MATERIALS:\n${adminSettings.instructionFiles.map(f => `--- FILE: ${f.name} ---\n${f.content}`).join('\n')}`
    : "";

  const strictnessInstructions = {
    low: "Baseline check. Be lenient.",
    medium: "Standard professional audit.",
    high: "Strict compliance. Penalize generic advice."
  };

  let finalPrompt = adminSettings.promptTemplate
    .replace(/{{url}}/g, url)
    .replace(/{{content}}/g, content.slice(0, 45000))
    .replace(/{{focusArea}}/g, criteria.focusArea)
    .replace(/{{strictness}}/g, strictnessInstructions[criteria.strictness])
    .replace(/{{customInstructions}}/g, criteria.customInstructions || "None");

  finalPrompt += knowledgeBaseContext;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: finalPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: criteria.strictness === 'high' ? 0.1 : 0.3,
        maxOutputTokens: 8192,
      },
    });

    let jsonText = response.text || "";

    // Cleanup: Remove markdown code fences if present (e.g. ```json ... ```)
    jsonText = jsonText.replace(/^```json\s*/i, '').replace(/\s*```$/, '');

    if (!jsonText) throw new Error("Empty response from model.");

    const parsedData = JSON.parse(jsonText);

    const priorityOrder: Record<string, number> = { 'High': 3, 'Medium': 2, 'Low': 1 };

    if (parsedData.recommendations && Array.isArray(parsedData.recommendations)) {
      parsedData.recommendations.sort((a: Recommendation, b: Recommendation) => 
        (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0)
      );
    } else {
        parsedData.recommendations = [];
    }

    return {
      url,
      pageTitle,
      timestamp: Date.now(),
      ...parsedData
    };
  } catch (error: any) {
    console.error("Analysis Error:", error);
    return {
      url,
      pageTitle,
      timestamp: Date.now(),
      seoScore: 0,
      eeatScore: 0,
      llmOptimizationScore: 0,
      isYMYL: false,
      summary: "Analysis Error",
      strengths: [],
      weaknesses: [],
      recommendations: [],
      keywordGaps: [],
      lsiKeywords: [],
      llmEntities: [],
      sentiment: { label: "Neutral", score: 0, explanation: "Failed to analyze." },
      error: error.message || "Unknown AI error."
    };
  }
};

