import CustomSelect from './components/CustomSelect';

const INITIAL_CRITERIA: AnalysisCriteria = {
  focusArea: 'General SEO',
  strictness: 'medium',
  customInstructions: ''
};

const GEO_PROMPT = `
Analyze the following web page content located at: {{url}}

Content Preview:
{{content}}

Analysis Criteria:
- Focus Area: {{focusArea}}
- Strictness Level: {{strictness}}
- User Custom Instructions: {{customInstructions}}

--- AUDIT INSTRUCTIONS ---
You are a Senior SEO Auditor and Content Strategist. Your goal is to analyze the content against high standards of Google's E-E-A-T and modern "Helpful Content" signals.
Use the following strict guidelines to evaluate the content.

1. Authorship & E-E-A-T (Critical)
   - Is there a real, named author? (Generic "Team" or "Staff" is a negative signal).
   - Are there clear credentials, job titles, or links to LinkedIn/Bio pages?
   - Originality: Does the content cite original research, first-hand data, or unique case studies? Or is it just aggregating existing info?
   - Expertise: Are there expert quotes? Note: Quotes in images are NOT readable by crawlers and should be flagged as an issue.

2. Structure & Journalism Style
   - Inverted Pyramid: Does it start with the "Most Important Point" or answer? Avoid academic intros that bury the lede.
   - Headings: Check hierarchy (H1 -> H2 -> H3). H1 must be unique. H2s should be informative (e.g., questions users ask).
   - Sentence Structure: One sentence = One idea. Flag long, complex sentences ("Walls of text").
   - Formatting: Look for tables, numbered lists, and visual breaks. (Tables increase citation rates).

3. AI & LLM Optimization (GEO - Generative Engine Optimization)
   - Direct Answers: Does the content contain concise (40-60 word) definition blocks that AI can easily extract as a featured snippet?
   - Numeric Anchors: Does it use specific data points (e.g., "cited 40% more often") rather than vague claims ("significant growth")?
   - Context: Are user pain points explicitly named and connected to the solution?
   - Entities: Does the content establish clear relationships between key entities (People, Places, Concepts) for Knowledge Graph construction?

4. Technical & UX
   - CTA: Are Call-to-Actions value-led and specific? (Avoid generic "Click here").
   - Internal Links: Are there 2-10 relevant internal links with descriptive anchor text?
   - External Links: Are sources cited? (Opinions/Stats should link to sources).

--- OUTPUT REQUIREMENTS ---
Provide a JSON response with a COMPREHENSIVE list of recommendations (aim for 25-30 granular items).
For each recommendation:
- Priority: High (EEAT/Safety/Broken), Medium (Optimization), Low (Polish).
- Action: Short title.
- Description: What is wrong.
- Affected Content: Quote the exact text, header, or section.
- Fix Steps: Step-by-step instructions.
- Expected Impact: Specific benefit.

Additionally, provide:
- strengths: List 3-5 top performing assets.
- weaknesses: List 3-5 urgent vulnerabilities.
- lsiKeywords: List 5-10 LSI keywords.
- llmEntities: List 5-10 key entities for knowledge mapping.
- sentiment: { label, score, explanation }

Do NOT be lenient.
`.trim();

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    mode: AnalysisMode.SINGLE,
    urls: [],
    results: [],
    isAnalyzing: false,
    currentProgress: 0,
    progressStatus: 'Ready',
    selectedModel: ModelType.FLASH,
    criteria: INITIAL_CRITERIA,
    showAdmin: false,
    showProxy: false,
    isAdminAuthenticated: false,
    adminSettings: {
        promptTemplate: GEO_PROMPT,
        instructionFiles: []
    }
  });

  const [customProxies, setCustomProxies] = useState<CustomProxy[]>([]);
  const [inputUrl, setInputUrl] = useState('');
  const [bulkInput, setBulkInput] = useState('');
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const saved = loadAdminSettings();
    if (saved) setState(prev => ({ ...prev, adminSettings: saved }));
    try {
      const savedProxies = localStorage.getItem('content_audit_user_proxies');
      if (savedProxies) setCustomProxies(JSON.parse(savedProxies));
    } catch (e) {}
  }, []);

  const handleOpenKeySelector = async () => {
    // @ts-ignore
    if (window.aistudio) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
    }
  };

  const currentTargetsCount = state.mode === AnalysisMode.SINGLE 
    ? (inputUrl.trim() ? 1 : 0) 
    : bulkInput.split('\n').map(u => u.trim()).filter(Boolean).length;

  const handleStartAnalysis = useCallback(async () => {
    if (abortControllerRef.current) abortControllerRef.current.abort();
    const controller = new AbortController();
    abortControllerRef.current = controller;

    let targets = state.mode === AnalysisMode.SINGLE 
      ? [inputUrl].filter(Boolean) 
      : bulkInput.split('\n').map(u => u.trim()).filter(Boolean);

    if (targets.length === 0) return;

    setState(prev => ({ 
      ...prev, 
      isAnalyzing: true, 
      results: [], 
      currentProgress: 0,
      progressStatus: 'Initializing secure audit...' 
    }));

    const finalResults: AnalysisResult[] = [];

    for (let i = 0; i < targets.length; i++) {
      if (controller.signal.aborted) break;
      const url = targets[i];
      const stepBase = (i / targets.length) * 100;
      const stepSize = 100 / targets.length;

      try {
        setState(prev => ({ ...prev, progressStatus: `Connecting to ${url}...`, currentProgress: Math.round(stepBase + (stepSize * 0.1)) }));
        const scrape = await scrapeUrl(url, customProxies, (s) => {
          setState(prev => ({ ...prev, progressStatus: s }));
        }, controller.signal);

        if (controller.signal.aborted) break;

        if (!scrape.success) {
          finalResults.push({ 
              url, timestamp: Date.now(), seoScore: 0, eeatScore: 0, llmOptimizationScore: 0, isYMYL: false, 
              summary: "Analysis Halted", strengths: [], weaknesses: [], recommendations: [], keywordGaps: [],
              lsiKeywords: [], llmEntities: [], sentiment: { label: 'Neutral', score: 50, explanation: 'Analysis failed.' },
              error: scrape.error 
          });
        } else {
          setState(prev => ({ ...prev, progressStatus: `Gemini performing semantic audit...`, currentProgress: Math.round(stepBase + (stepSize * 0.5)) }));
          const analysis = await analyzeContent(url, scrape.title, scrape.content, state.criteria, state.selectedModel, state.adminSettings);

          if (analysis.error?.includes("Requested entity was not found") || analysis.error?.includes("API_KEY_INVALID")) {
            await handleOpenKeySelector();
            throw new Error("Initial API key failed. Please re-run the audit after selecting your project key.");
          }

          finalResults.push(analysis);
        }
      } catch (err: any) {
        finalResults.push({ 
            url, timestamp: Date.now(), seoScore: 0, eeatScore: 0, llmOptimizationScore: 0, isYMYL: false, 
            summary: "System Error", strengths: [], weaknesses: [], recommendations: [], keywordGaps: [],
            lsiKeywords: [], llmEntities: [], sentiment: { label: 'Neutral', score: 50, explanation: 'System error.' },
            error: err.message 
        });
      }

      setState(prev => ({ 
        ...prev, 
        results: [...finalResults], 
        currentProgress: Math.round(((i + 1) / targets.length) * 100) 
      }));
    }

    setState(prev => ({ ...prev, isAnalyzing: false, progressStatus: 'Audit Complete' }));
  }, [state.mode, state.criteria, state.selectedModel, state.adminSettings, inputUrl, bulkInput, customProxies]);

  const handleStopAnalysis = () => {
    abortControllerRef.current?.abort();
    setState(prev => ({ ...prev, isAnalyzing: false, progressStatus: 'Session Terminated' }));
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] text-slate-900 flex flex-col font-inter pb-16">
      {/* Navigation */}
      <nav className="fixed w-full z-40 top-0 start-0 border-b border-white/20 bg-white/80 backdrop-blur-md shadow-sm">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center shadow-lg transform hover:rotate-3 transition-transform">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </div>
