             {state.results.length === 0 && !state.isAnalyzing ? (
               <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[500px] border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white/40 p-12 text-center animate-in zoom-in-95">
                 <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mb-6 shadow-inner">
                    <svg className="w-12 h-12 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" /></svg>
                 </div>
                 <h3 className="text-2xl font-bold text-slate-700">Intelligence Ready</h3>
                 <p className="text-slate-500 max-w-xs mx-auto mt-2">Input target URLs to begin multi-vector content auditing and GEO assessment.</p>
               </div>
             ) : (
               <div className="space-y-10">
                 {state.results.map((result, index) => (
                    <div key={index} className="animate-slide-up" style={{ animationDelay: `${index * 0.1}s` }}>
                        <ResultCard result={result} />
                    </div>
                 ))}
                 {state.isAnalyzing && state.results.length < currentTargetsCount && (
                    <div className="bg-white/50 border border-dashed border-blue-200 rounded-3xl p-12 flex flex-col items-center justify-center gap-4 animate-pulse">
                        <div className="w-10 h-10 border-4 border-blue-100 border-t-blue-500 rounded-full animate-spin"></div>
                        <p className="text-sm font-semibold text-blue-500">Processing next segment...</p>
                    </div>
                 )}
               </div>
             )}
          </div>
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 w-full bg-slate-900 text-slate-400 text-[10px] py-2 px-6 z-50 flex justify-between border-t border-slate-700/50 backdrop-blur-sm">
          <div className="flex gap-4">
            <span className="mono opacity-50 uppercase">PROJECT: ANTAKO_AUDIT_V2</span>
            <span className="mono opacity-50 uppercase">AUTH: AUTO_SECURE</span>
          </div>
          <span className="mono">STABLE_PRODUCTION // v1.2.8</span>
      </footer>

      {state.showAdmin && <AdminPanel settings={state.adminSettings} onSave={(s) => { setState(prev => ({...prev, adminSettings: s})); saveAdminSettings(s); }} onClose={() => setState(prev => ({ ...prev, showAdmin: false }))} />}
      {state.showProxy && <ProxyModal onClose={() => setState(prev => ({ ...prev, showProxy: false }))} onSave={setCustomProxies} initialProxies={customProxies} />}
      {showPasswordModal && <PasswordModal onAuthenticated={() => { setState(prev => ({...prev, isAdminAuthenticated: true, showAdmin: true})); setShowPasswordModal(false); }} onClose={() => setShowPasswordModal(false)} />}
    </div>
  );
};

