            <span className="mono opacity-50 uppercase tracking-widest">BACKEND: {systemHealth?.connected ? 'STABLE' : 'OFFLINE'}</span>
            <span className="mono opacity-50 uppercase tracking-widest">VAULT: {systemHealth?.provider || 'CONNECTING...'}</span>
            {systemHealth?.latency && <span className="mono opacity-30">RESPONSE: {systemHealth.latency}</span>}
          </div>
          <span className="mono">INTERNAL_TOOL_ANTAKO_NP // v1.3.0-AUTOMATED</span>
