      {state.showAdmin && <AdminPanel settings={state.adminSettings} onSave={(s) => { setState(prev => ({...prev, adminSettings: s})); saveAdminSettings(s); }} onClose={() => setState(prev => ({ ...prev, showAdmin: false }))} />}
      {state.showProxy && <ProxyModal onClose={() => setState(prev => ({ ...prev, showProxy: false }))} onSave={setCustomProxies} initialProxies={customProxies} />}
      {showPasswordModal && <PasswordModal onAuthenticated={() => { setState(prev => ({...prev, isAdminAuthenticated: true, showAdmin: true})); setShowPasswordModal(false); }} onClose={() => setShowPasswordModal(false)} />}
    </div>
  );
};

