const INITIAL_CRITERIA: AnalysisCriteria = {
  focusArea: 'General SEO',
  strictness: 'medium',
  customInstructions: ''
};

const GEO_PROMPT = `
Analyze the following web page content located at: {{url}}

Content Preview:
{{content}}

Analysis Criteria:
- Focus Area: {{focusArea}}
- Strictness Level: {{strictness}}
- User Custom Instructions: {{customInstructions}}

--- AUDIT INSTRUCTIONS ---
Analyze against E-E-A-T and Helpful Content signals.
1. Authorship (named author, credentials).
2. Structure (Inverted Pyramid, clean headings).
3. AI/LLM Optimization (Definition blocks, numeric anchors).
4. Technical CTAs and link structure.

Provide JSON output with scores and detailed actionable recommendations.
`.trim();

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    mode: AnalysisMode.SINGLE,
    urls: [],
    results: [],
    isAnalyzing: false,
    currentProgress: 0,
    progressStatus: 'Ready',
    selectedModel: ModelType.FLASH,
    criteria: INITIAL_CRITERIA,
    showAdmin: false,
    showProxy: false,
    isAdminAuthenticated: false,
    adminSettings: {
        promptTemplate: GEO_PROMPT,
        instructionFiles: []
    }
  });

  const [systemHealth, setSystemHealth] = useState<SystemHealth | null>(null);
  const [customProxies, setCustomProxies] = useState<CustomProxy[]>([]);
  const [inputUrl, setInputUrl] = useState('');
  const [bulkInput, setBulkInput] = useState('');
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const saved = loadAdminSettings();
    if (saved) setState(prev => ({ ...prev, adminSettings: saved }));

    // Connect to "Backend Point" on application mount
    checkBackendHealth().then(setSystemHealth);

    try {
      const savedProxies = localStorage.getItem('content_audit_user_proxies');
      if (savedProxies) setCustomProxies(JSON.parse(savedProxies));
    } catch (e) {}
  }, []);

  const currentTargetsCount = state.mode === AnalysisMode.SINGLE 
    ? (inputUrl.trim() ? 1 : 0) 
    : bulkInput.split('\n').map(u => u.trim()).filter(Boolean).length;

  const handleStartAnalysis = useCallback(async () => {
    if (abortControllerRef.current) abortControllerRef.current.abort();
    const controller = new AbortController();
    abortControllerRef.current = controller;

    let targets = state.mode === AnalysisMode.SINGLE 
      ? [inputUrl].filter(Boolean) 
      : bulkInput.split('\n').map(u => u.trim()).filter(Boolean);

    if (targets.length === 0) return;

    setState(prev => ({ 
      ...prev, 
      isAnalyzing: true, 
      results: [], 
      currentProgress: 0,
      progressStatus: 'Establishing secure backend handshake...' 
    }));

    const finalResults: AnalysisResult[] = [];

    for (let i = 0; i < targets.length; i++) {
      if (controller.signal.aborted) break;
      const url = targets[i];
      const stepBase = (i / targets.length) * 100;
      const stepSize = 100 / targets.length;

      try {
        setState(prev => ({ ...prev, progressStatus: `Credentials verified. Scraping target...`, currentProgress: Math.round(stepBase + (stepSize * 0.1)) }));
        const scrape = await scrapeUrl(url, customProxies, (s) => {
          setState(prev => ({ ...prev, progressStatus: s }));
        }, controller.signal);

        if (controller.signal.aborted) break;

        if (!scrape.success) {
          finalResults.push({ 
              url, timestamp: Date.now(), seoScore: 0, eeatScore: 0, llmOptimizationScore: 0, isYMYL: false, 
              summary: "Audit Interrupted", strengths: [], weaknesses: [], recommendations: [], keywordGaps: [],
              lsiKeywords: [], llmEntities: [], sentiment: { label: 'Neutral', score: 50, explanation: 'Scraping failed.' },
              error: scrape.error 
          });
        } else {
          setState(prev => ({ ...prev, progressStatus: `Processing deep analysis via Gemini...`, currentProgress: Math.round(stepBase + (stepSize * 0.5)) }));
          const analysis = await analyzeContent(url, scrape.title, scrape.content, state.criteria, state.selectedModel, state.adminSettings);
          finalResults.push(analysis);
        }
      } catch (err: any) {
        finalResults.push({ 
            url, timestamp: Date.now(), seoScore: 0, eeatScore: 0, llmOptimizationScore: 0, isYMYL: false, 
            summary: "Vault Error", strengths: [], weaknesses: [], recommendations: [], keywordGaps: [],
            lsiKeywords: [], llmEntities: [], sentiment: { label: 'Neutral', score: 50, explanation: 'System error.' },
            error: err.message 
        });
      }

      setState(prev => ({ 
        ...prev, 
        results: [...finalResults], 
        currentProgress: Math.round(((i + 1) / targets.length) * 100) 
      }));
    }

    setState(prev => ({ ...prev, isAnalyzing: false, progressStatus: 'Session Complete' }));
  }, [state.mode, state.criteria, state.selectedModel, state.adminSettings, inputUrl, bulkInput, customProxies]);

  const handleStopAnalysis = () => {
    abortControllerRef.current?.abort();
    setState(prev => ({ ...prev, isAnalyzing: false, progressStatus: 'Aborted' }));
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] text-slate-900 flex flex-col font-inter pb-16">
      <nav className="fixed w-full z-40 top-0 start-0 border-b border-white/20 bg-white/80 backdrop-blur-md shadow-sm">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center shadow-lg transform hover:rotate-3 transition-transform">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </div>
              <span className="font-bold text-xl tracking-tight hidden sm:inline-block">ContentAudit<span className="text-blue-600">AI</span></span>
            </div>

            <div className="flex items-center gap-2">
               <div className="w-44 hidden md:block">
                 <CustomSelect 
                    value={state.selectedModel} 
                    onChange={(val) => setState(prev => ({ ...prev, selectedModel: val as ModelType }))} 
                    options={[
                        { value: ModelType.FLASH, label: 'Gemini 3 Flash' },
                        { value: ModelType.PRO, label: 'Gemini 3 Pro' },
                        { value: ModelType.FLASH_LITE, label: 'Flash Lite' }
                    ]} 
                 />
               </div>
               <div className="flex items-center border-l border-slate-100 ml-2 pl-2 gap-1">
                 <button onClick={() => setState(prev => ({ ...prev, showProxy: true }))} className="p-2 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all" title="Network"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg></button>
                 <button onClick={() => state.isAdminAuthenticated ? setState(prev => ({...prev, showAdmin: true})) : setShowPasswordModal(true)} className="p-2 text-slate-500 hover:text-purple-600 hover:bg-purple-50 rounded-lg transition-all" title="Logic Admin"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066-1.543.94-3.31-.826-2.37-2.37-1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg></button>
               </div>
            </div>
