  latency: string;
  status: 'ONLINE' | 'OFFLINE';
}

/**
 * Direct access to the environment key.
 * The Vite config ensures process.env.API_KEY is replaced with the real value.
 */
export const getSecureApiKey = async (): Promise<string> => {
  const apiKey = process.env.API_KEY;

  if (!apiKey) {
    throw new Error("VAULT_SYNC_ERROR: The secure backend did not return a valid API_KEY. Check environment variables.");
  }

  return apiKey;
};

