        },
        required: ['category', 'priority', 'action', 'description', 'affectedContent', 'fixSteps', 'expectedImpact']
      }
    },
    keywordGaps: { type: Type.ARRAY, items: { type: Type.STRING } },
    lsiKeywords: { type: Type.ARRAY, items: { type: Type.STRING } },
    llmEntities: { type: Type.ARRAY, items: { type: Type.STRING } },
    sentiment: { 
      type: Type.OBJECT,
      properties: {
        label: { type: Type.STRING },
        score: { type: Type.NUMBER },
        explanation: { type: Type.STRING }
      },
      required: ['label', 'score', 'explanation']
    }
  },
  required: ['seoScore', 'eeatScore', 'llmOptimizationScore', 'isYMYL', 'summary', 'strengths', 'weaknesses', 'recommendations', 'lsiKeywords', 'llmEntities', 'sentiment']
};

export const analyzeContent = async (
  url: string,
  pageTitle: string,
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType,
  adminSettings: AdminSettings
): Promise<AnalysisResult> => {
  const apiKey = await getSecureApiKey();
  const ai = new GoogleGenAI({ apiKey });

  const isPro = model.includes('pro');
  const strictnessMap = { low: 0.5, medium: 0.3, high: 0.1 };

  const prompt = `${adminSettings.promptTemplate}

  URL: ${url}
  TITLE: ${pageTitle}
  CONTENT: ${content.substring(0, 30000)}
  FOCUS: ${criteria.focusArea}
  INSTRUCTIONS: ${criteria.customInstructions}`;

  const response = await ai.models.generateContent({
    model: model,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: analysisSchema,
      temperature: strictnessMap[criteria.strictness] || 0.3,
      thinkingConfig: isPro ? { thinkingBudget: 32768 } : undefined
    }
  });

  return {
    url,
    pageTitle,
    timestamp: Date.now(),
    ...JSON.parse(response.text)
  };
};

