export const scrapeUrl = async (
  url: string, 
  customProxies: CustomProxy[] = [],
  onStatusUpdate?: (status: string) => void,
  signal?: AbortSignal
): Promise<ScrapingResult> => {
  if (!url || !url.startsWith('http')) {
    return { url, content: '', title: '', success: false, error: 'Invalid URL. Must include http/https.' };
  }

  // List of proxies that work in browser
  const proxies = [
    { name: 'Jina Reader', url: (u: string) => `https://r.jina.ai/${u}` },
    { name: 'AllOrigins', url: (u: string) => `https://api.allorigins.win/raw?url=${encodeURIComponent(u)}` },
    { name: 'CodeTabs', url: (u: string) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(u)}` }
  ];

  let lastError = '';

  for (const proxy of proxies) {
    if (signal?.aborted) break;
    try {
      onStatusUpdate?.(`Connecting via ${proxy.name}...`);
      const response = await fetchWithTimeout(proxy.url(url));
      const html = await response.text();

      if (!html || html.length < 100) throw new Error("Response too short.");

      let title = url;
      let content = '';

      if (proxy.name === 'Jina Reader') {
        // Jina returns markdown directly
        const lines = html.split('\n');
        const titleLine = lines.find(l => l.startsWith('# '));
        title = titleLine ? titleLine.replace('# ', '').trim() : url;
        content = html;
      } else {
        // Generic HTML parsing
        const doc = new DOMParser().parseFromString(html, 'text/html');
        title = doc.title || url;
        // Clean HTML
        doc.querySelectorAll('script, style, nav, footer, iframe, ads').forEach(el => el.remove());
        content = (doc.querySelector('main, article') || doc.body).innerText;
      }

      onStatusUpdate?.(`Content retrieved successfully.`);
      return { 
        url, 
        content: content.replace(/\s+/g, ' ').trim().slice(0, 20000), 
        title, 
        success: true 
      };
    } catch (err: any) {
      console.warn(`Proxy ${proxy.name} failed:`, err);
      lastError = err.message;
    }
  }

  return { url, content: '', title: '', success: false, error: `Failed to fetch page: ${lastError}` };
};

