import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisCriteria, AnalysisResult, ModelType, AdminSettings, Recommendation } from "../types";
import { getSecureApiKey } from "./authService";

const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    seoScore: { type: Type.NUMBER },
    eeatScore: { type: Type.NUMBER },
    llmOptimizationScore: { type: Type.NUMBER },
    isYMYL: { type: Type.BOOLEAN },
    summary: { type: Type.STRING },
    strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
    weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
    recommendations: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING },
          priority: { type: Type.STRING },
          action: { type: Type.STRING },
          description: { type: Type.STRING },
          affectedContent: { type: Type.STRING },
          fixSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
          expectedImpact: { type: Type.STRING }
        },
        required: ['category', 'priority', 'action', 'description', 'affectedContent', 'fixSteps', 'expectedImpact']
      }
    },
    keywordGaps: { type: Type.ARRAY, items: { type: Type.STRING } },
    lsiKeywords: { type: Type.ARRAY, items: { type: Type.STRING } },
    llmEntities: { type: Type.ARRAY, items: { type: Type.STRING } },
    sentiment: { 
      type: Type.OBJECT,
      properties: {
        label: { type: Type.STRING },
        score: { type: Type.NUMBER },
        explanation: { type: Type.STRING }
      },
      required: ['label', 'score', 'explanation']
    }
  },
  required: ['seoScore', 'eeatScore', 'llmOptimizationScore', 'isYMYL', 'summary', 'strengths', 'weaknesses', 'recommendations', 'lsiKeywords', 'llmEntities', 'sentiment']
};

export const analyzeContent = async (
  url: string,
  pageTitle: string,
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType,
  adminSettings: AdminSettings
): Promise<AnalysisResult> => {
  try {
    const apiKey = await getSecureApiKey();
    const ai = new GoogleGenAI({ apiKey });

    const isPro = model.includes('pro');
    const strictnessMap = { low: 0.5, medium: 0.3, high: 0.1 };

    const prompt = `${adminSettings.promptTemplate}

    URL: ${url}
    TITLE: ${pageTitle}
    CONTENT: ${content.substring(0, 30000)}
    FOCUS: ${criteria.focusArea}
    INSTRUCTIONS: ${criteria.customInstructions}`;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: strictnessMap[criteria.strictness] || 0.3,
        thinkingConfig: isPro ? { thinkingBudget: 32768 } : undefined
      }
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Model returned empty text response.");

    const parsedData = JSON.parse(resultText);

    // Manual Sort Priority: High > Medium > Low
    const priorityOrder: Record<string, number> = { 'High': 3, 'Medium': 2, 'Low': 1 };
    if (parsedData.recommendations && Array.isArray(parsedData.recommendations)) {
      parsedData.recommendations.sort((a: Recommendation, b: Recommendation) => 
        (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0)
      );
    }

    return {
      url,
      pageTitle,
      timestamp: Date.now(),
      ...parsedData
    };
  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    throw new Error(`Analysis failed: ${error.message}`);
  }
};

