                                    <ul className="space-y-2">
                                        {rec.fixSteps.map((step, i) => (
                                            <li key={i} className="flex gap-3 text-sm text-slate-700">
                                                <span className="flex-shrink-0 w-5 h-5 rounded-full bg-slate-100 text-slate-500 text-[10px] font-bold flex items-center justify-center border border-slate-200">{i+1}</span>
                                                <span>{step}</span>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                             </div>
                        </div>
                    )}
                </div>
               );
            })}
          </div>
        )}

        {activeTab === 'details' && (
           <div className="space-y-8">
              {/* Sentiment Profiling Section */}
              <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm relative overflow-hidden">
                   <div className="absolute top-0 right-0 p-8 opacity-10">
                        <svg className="w-32 h-32 text-slate-900" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 14.5v-1a.5.5 0 01.5-.5h1a.5.5 0 01.5.5v1a.5.5 0 01-.5.5h-1a.5.5 0 01-.5-.5zm1.5-3.62c-.17.34-.52.5-.83.33-.29-.15-.41-.5-.27-.81.65-1.46 1.84-2.15 3.09-2.15 1.55 0 2.8 1.15 2.8 2.57 0 .91-.56 1.71-1.39 2.14l-.53.27c-.49.26-.79.76-.79 1.32v.06c0 .32-.23.6-.55.63-.34.03-.64-.22-.67-.56v-.12c0-.98.53-1.87 1.38-2.33l.53-.27c.52-.27.86-.77.86-1.34 0-.82-.72-1.48-1.61-1.48-.96 0-1.86.67-2.02 1.73z"/></svg>
                   </div>

                   <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                       <span className="w-2 h-2 rounded-full bg-purple-500"></span>
                       Deep Sentiment Profiling
                   </h4>

                   <div className="flex flex-col md:flex-row gap-8 items-start relative z-10">
                        {/* Score Gauge */}
                        <div className="flex-shrink-0 flex flex-col items-center gap-2">
                             <div className="relative w-32 h-32 flex items-center justify-center">
                                 <svg className="w-full h-full" viewBox="0 0 36 36">
                                     <path d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke="#f1f5f9" strokeWidth="3" />
                                     <path d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke={result.sentiment.score > 60 ? '#10b981' : result.sentiment.score > 40 ? '#f59e0b' : '#ef4444'} strokeWidth="3" strokeDasharray={`${result.sentiment.score}, 100`} className="animate-[spin_1s_ease-out_reverse]" />
                                 </svg>
                                 <div className="absolute inset-0 flex flex-col items-center justify-center">
                                     <span className="text-3xl font-bold text-slate-800">{result.sentiment.score}</span>
                                 </div>
                             </div>
                             <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide border ${
                                 result.sentiment.label.toLowerCase().includes('positive') ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                                 result.sentiment.label.toLowerCase().includes('negative') ? 'bg-rose-50 text-rose-600 border-rose-100' :
                                 'bg-slate-50 text-slate-600 border-slate-100'
                             }`}>
                                 {result.sentiment.label}
                             </span>
                        </div>

                        {/* Analysis Text */}
                        <div className="flex-grow">
                             <p className="text-slate-600 leading-relaxed text-sm bg-slate-50/50 p-6 rounded-2xl border border-slate-100 italic">
                                "{result.sentiment.explanation}"
                             </p>
                        </div>
                   </div>
              </div>

              {/* Semantic Analysis Grid */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {/* Keyword Gaps */}
                  <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col">
                      <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Semantic Keyword Gaps</h4>
                      <div className="flex flex-wrap gap-2 content-start">
                          {result.keywordGaps.map((k, i) => (
                              <span key={i} className="px-3 py-1.5 bg-slate-50 text-slate-700 rounded-lg text-xs font-bold border border-slate-100 hover:bg-white hover:border-blue-200 transition-all cursor-default">
                                  {k}
                              </span>
                          ))}
                      </div>
                  </div>

                  {/* LSI Keywords */}
                  <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col">
                      <h4 className="text-[10px] font-bold text-blue-400 uppercase tracking-widest mb-4">LSI Opportunities</h4>
                      <div className="flex flex-wrap gap-2 content-start">
                          {result.lsiKeywords.map((k, i) => (
                              <span key={i} className="px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg text-xs font-bold border border-blue-100 hover:bg-white hover:border-blue-300 transition-all cursor-default">
                                  {k}
                              </span>
                          ))}
                          {result.lsiKeywords.length === 0 && <span className="text-xs text-slate-400 italic">No specific LSI keywords identified.</span>}
                      </div>
                  </div>

                  {/* LLM Entities */}
                  <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col">
                      <h4 className="text-[10px] font-bold text-purple-400 uppercase tracking-widest mb-4">LLM Entity Mapping</h4>
                      <div className="flex flex-col gap-2">
                          {result.llmEntities.map((k, i) => (
                              <div key={i} className="flex items-center gap-2 px-3 py-2 bg-purple-50/50 rounded-xl border border-purple-50">
                                  <svg className="w-3 h-3 text-purple-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
                                  <span className="text-xs font-bold text-slate-700">{k}</span>
                              </div>
                          ))}
                          {result.llmEntities.length === 0 && <span className="text-xs text-slate-400 italic">No entities extracted.</span>}
                      </div>
                  </div>
              </div>
           </div>
        )}
      </div>

      {showPromptModal && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-900/80 backdrop-blur-md p-4 animate-in fade-in duration-300">
              <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl flex flex-col max-h-[85vh] overflow-hidden animate-in zoom-in-95">
                  <div className="p-8 border-b border-slate-100 flex justify-between items-center">
                      <h3 className="text-xl font-bold text-slate-900">Strategic Implementation Plan</h3>
                      <button onClick={() => setShowPromptModal(false)} className="text-slate-400 hover:text-slate-600"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                  </div>
                  <div className="p-8 overflow-y-auto bg-slate-50 flex-grow">
                      <textarea readOnly value={generatedPrompt} className="w-full h-80 p-6 text-sm mono text-slate-700 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none leading-relaxed shadow-inner" />
                  </div>
                  <div className="p-8 bg-white flex justify-end gap-4">
                      <button onClick={() => { navigator.clipboard.writeText(generatedPrompt); alert("Copied!"); }} className="px-8 py-3 bg-slate-900 text-white font-bold rounded-2xl shadow-xl hover:bg-black transition-all">Copy Plan</button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default ResultCard;
